"""Freeze six full travel proposals and actual unresolved decisions; adopt nothing."""
from copy import deepcopy
from datetime import datetime, timezone
import json, zipfile
from apply_di7_ap_as_01 import G, R, A, info, encoded
from prepare_ac5_current_interfaces_01 import at

IDS=['dimension-door','dimensional-shift','instant-summons','mystic-gate','teleport-object','teleportation-circle']
FORKS=[
('TR6-Q01',['dimension-door'],'Universal source says teleport up to500ft; separate accepted Conjuration Dimensional Door requires a known location.', 'A: preserve proposed self/gear with precise measured-vector designation in addition to personally known/perceived destination. B: require the accepted Conjuration known-location gate for both.', 'Recommend A as an explicit Universal-only difference; the measured vector begins at a genuinely known current anchor and supplies no remote sight, safe-square search, passenger or class/school merge.'),
('TR6-Q02',['dimension-door','dimensional-shift','mystic-gate','teleportation-circle'],'Passenger permissions differ across the full old proposals and accepted transports.', 'A: DimensionDoor excludes all other creatures; Shift/Gate/Circle permit actually carried creature bodies only under their own explicit local rules. B: impose one identical passenger rule on all transports.', 'Recommend A, preserving real custody/anatomy/pounds/Load and every passenger own blocker. Carrying is not a consent spell and grants no new capture or free pickup. Do not turn a creature-origin object-shaped body into eligible ordinary object payload.'),
('TR6-Q03',['teleport-object'],'Source any nonliving item<=500lb within100ft; earlier completion adds both caster range and source-to-destination distance.', 'A: preserve actual individually perceived source and perceived supported destination, both<=100caster and destination<=100source, with destination path exemption. B: choose only one100ft bound or allow unsupported damaging drops.', 'Recommend A as explicit proposed scope, retaining physical support/whole payload at rest and no extra damage. Source selection still needs actual LoE; an unseen destination is not supplied by the path exception.'),
('TR6-Q04',['teleport-object','dimensional-shift'],'TeleportObject permits ordinary loose worn/held gear with WIS custody resistance; Shift permits loose held objects with CHA and excludes worn/fastened objects.', 'A: retain these separate deliberate source completions with all actual custodians checked. B: harmonize the eligibility/save across both cards.', 'Recommend A unless GPT identifies a concrete inconsistency requiring a local replacement. Define loose worn versus secured fastening operationally; do not rip an implant, locked restraint, built-in assembly or body part free. Ownership and actual current physical custody remain different predicates.'),
('TR6-Q05',['dimensional-shift'],'Any target within100ft is a true two-way swap with no printed size or mass ceiling.', 'A: creature/discrete object, unwilling creature or loose-object holder CHA, two simultaneous whole-body fits using actual reference positions/orientations. B: add size/weight cap or adjacent fallback.', 'Recommend A. Each destination excludes only the departing pair own volumes; carried groups retain real geometry. Define reference anchors in each current case so a pebble surface point is not silently a humanoid center. One invalid endpoint blocks the entire paid swap.'),
('TR6-Q06',['dimensional-shift'],'Source target may genuinely die or change form before resolution; prior proposal retains same physical remains where still legal.', 'A: retain same body lineage and revalidate its then-current creature/object/custody/placement predicates. B: automatically fail every type change or choose a replacement target.', 'Recommend A only for the same actual already-selected physical identity; no corpse resurrection, substituted corpse, duplication or restored gear. Truly removed/consumed body supplies no target. Caster actual death/incapacity still follows real cast-resolution rules.'),
('TR6-Q07',['mystic-gate'],'Source minute two-way portal; Core has minute but no concentration or aperture dimensions.', 'A: earlier concentration60sec with two fixed supported5x8apertures, each<=60caster and pair<=60. B: nonconcentration minute or a different explicit geometry.', 'Recommend A as named new local design, preserving source two-way minute function and no one-transit cap. It does not inherit ArcanePortal3x5/500lb/singletraveler limits or AlignmentPortal planar classification/sight permission.'),
('TR6-Q08',['mystic-gate'],'Whole driven wagon/puller/passenger assembly permission is a new extension beyond ordinary creature crossing.', 'A: allow one actual legal coupled moving transport group if every part clears both aperture and complete exit, paying real drive/puller/movement costs. B: restrict to individually walking/carried creature groups.', 'Recommend A conditionally, but no authored successful vehicle case without an actual sourced vehicle, coupling, draft and capacity model. The original failed too-wide wagon case does not prove a successful vehicle transit. No detached cargo or invented handling action.'),
('TR6-Q09',['mystic-gate'],'Proposed crossing uses5ft movement, opaque endpoints and no independent projectile/fluid/falling-object flow.', 'A: voluntary real movement crossing only, additive actual terrain/crawl/squeeze costs, original sixty-second deadline and atomic paired capacity. B: import AlignmentPortal forced-crossing or ordinary sight-through.', 'Recommend A for this distinct teleport portal. Clarify facing mapping and which aperture side is entry/exit before current geometry cases; nearest legal adjacent placement cannot search beyond barriers. Known illegal attempts do not spend fictitious crossing movement; actual already-spent approach remains spent.'),
('TR6-Q10',IDS,'Different accepted sources distinguish teleport, planar and physical gateway travel; names alone are insufficient.', 'A: classify these six locally as same-plane teleport transactions, with Gate/Circle formation separate from actual transit. B: treat every portal as nonteleport by analogy to AlignmentPortal.', 'Recommend A consistent with prior teleport wording, explicitly for these identities only. DimensionalAnchor uses every actual transported body endpoint; NoEscape/Verdict voluntary wording and Reign benefit wording retain exact meanings. No global planar taxonomy or new bypass follows. A source-specific gate can form while actual transit is blocked.'),
('TR6-Q11',['instant-summons'],'Source initial60ft,Action,concentrationminute,prepare object to hand; later distance/activation unspecified.', 'A: earlier owned/consented50lb5ft-cube object, one actual BA recall within1mile during original60sec. B: use60ft for recall or a different finite explicit scope.', 'Recommend A only as new remote retrieval rule, with real free hand/holding posture and both capacity limits. Initial owner consent does not override another creature actual custody at recall. No imported gem or permanent tag.'),
('TR6-Q12',['instant-summons'],'One live recall relation binds one coherent object but its current contents/damage/custody can change.', 'A: current complete eligible container payload, one legal attempt consumes relation even on hidden failure, exact source clocks, no locator. B: snapshot original contents or allow repeated probes until success.', 'Recommend A. Preserve dropped/consumed contents as gone, no reconstruction of fragments, no living/creature-origin hidden payload. Initial explicit object/external custody and terminal recall checks do not grant targeting a melded inaccessible item. Actual suppression at object/caster must be source-qualified, not a remote empty-anchor guess.'),
('TR6-Q13',['teleportation-circle'],'Source permanent until dispelled,ten-minute cast,60ft and material/focus alternative.', 'A: earlier fixed10ft-diameter inscribed site, ten uninterrupted minutes with concentration during work and actual Actions, no concentration after completion. B: imported year ritual, unprinted material charge, or concentration permanent circle.', 'Recommend A. Actual casting costs/counters/work interruption remain separate from later operation. Supporting surface movement/destruction ends this site; ordinary cosmetic mark damage does not arbitrarily become a free dispel. No purchased gemstone/chalk price is invented.'),
('TR6-Q14',['teleportation-circle'],'One studied same-plane outbound destination, independent creator/custodian permission and unique permanent site IDs.', 'A: earlier ten-minute in-person destination study, destination local acceptance of origin ID, full paid Rebind preserving origin incoming ID/links. B: guessed/copied decorative address, automatic acceptance or free retarget.', 'Recommend A as explicit network rule. Resolve creator/custodian loss: absent a new approved recovery mechanism, no living consenting custodian means no authorized rebind/decommission/additional custodian; existing open valid links may continue. Do not invent soul authentication, inheritance or remote administrator powers.'),
('TR6-Q15',['teleportation-circle'],'One conscious traveler-group Action with no RP fee, one attempt per origin per six elapsed seconds.', 'A: earlier one fixed accepted link, origin whole footprint inside10ft disk and actual legal receiving space at/adjacent site, atomic failure with spent Action/cooldown. B: unlimited throughput, group independent activations or tactical remote landing.', 'Recommend A. A diameter10disk is not a10x10square: an unsqueezed Large10x10footprint does not wholly fit, while a centered Medium5x5footprint does. Give actual body/cargo heights and site overhead clearance; disk is not an invented ceiling. Any squeeze must independently be legal, not a free size change.'),
('TR6-Q16',['teleportation-circle','mystic-gate','dimension-door','dimensional-shift','teleport-object','instant-summons'],'Transport changes position, not work/rest/custody/expedition histories or cosmological facts.', 'A: retain real route bypass where permitted while downstream arrival, cargo claims, hazards, support and clocks still execute. B: automatic Extraction, settlement, supply conversion, reset or new plane connection.', 'Recommend A. Original Circle30min/30RP describes three casts, not destination-study/acceptance/travel/actual class resource sufficiency. Current cases need real acquired spells, hands/actions, capacity and entire endpoint bodies. Frozen original scenarios remain obligations, not proved current encounters.')
]

def main():
    out=R/'data/director/spell_review/transport_6_conference_01.json';root=A/'transport6-conference-01';check=A/'TRANSPORT_6_CONFERENCE_01_CHECK.json';archive=A/'DD_Transport_6_Conference_01.zip';req=A/'TRANSPORT_6_CONFERENCE_01_REQUEST.txt';prep=A/'TRANSPORT_6_CONFERENCE_01_PREPARATION.json'
    assert all(not p.exists() for p in [out,root,check,archive,req,prep])
    sources={};checks=[]
    def read(p):return json.loads(p.read_bytes())
    def bind(p):
        b=info(p);sources[b['path']]=b;return b
    def ck(label,v):
        checks.append({'check':label,'passed':bool(v)});assert v,label
    qp=R/'data/director/spell_review/remaining_work_queue_06.json';cp=R/'data/public/spell_playtests/catalog.json';ip=R/'data/public/spell_playtests/authored_review_index.json';rp=R/'data/director/spell_review/accepted_interface_registry_04.json';queue,catalog,index,reg=map(read,[qp,cp,ip,rp])
    for p in [qp,cp,ip,rp,R/'data/public/class_playtests/wizard.json',R/'data/public/class_playtests/cleric.json',R/'data/public/class_playtests/paladin.json',R/'data/public/expedition_candidate/complete_candidate.json',R/'tools/prepare_transport6_conference_01.py']:bind(p)
    for name in ['BODY_EQUIPMENT_PLAYTEST.md','COMBAT_ACTION_PLAYTEST.md','CREATURE_LIFECYCLE_PLAYTEST.md','CHARACTER_CREATION_PLAYTEST.md','VIDEO_GAME_ONLY_DIRECTIVE.md']:bind(R/'docs/mechanics'/name)
    records=[];shared={};cases=[]
    for ident in IDS:
        row=next(r for r in queue['rows'] if r['id']==ident);ck('Not already queued '+ident,row['currentGroup'] is None)
        prior=row['previousAuthoringMapRowUnchanged']['completeEarlierProposalRecords'][0];p=G/prior['source']['path'];ck('Full original source '+ident,bind(p)==prior['source']);doc=read(p);rec=at(doc,prior['recordPointer']);card=next(s for s in catalog['spells'] if s['id']==ident);entry=next(e for e in index['entries'] if e['id']==ident)
        ck('Complete procedure '+ident,rec['spellId']==ident and len(rec['procedure'])>100);ck('Unchanged exact access/source '+ident,rec['fullSourceAndCurrentAccessRecord']==card);ck('Pending identity '+ident,entry['authoredStatus']=='pending-authored-procedure')
        records.append({'spellId':ident,'source':info(p),'pointer':prior['recordPointer'],'completeOriginalRecordUnchanged':deepcopy(rec),'completeCurrentCatalogSourceAndAccess':deepcopy(card),'indexEntry':deepcopy(entry),'riskTier':'B' if ident=='dimension-door' else 'C','status':'Earlier full proposal; design choices not adopted.'})
        shared[str(p)]={'source':info(p),'completeOriginalSharedProposalUnchanged':deepcopy(doc['sharedProposal']),'completeOriginalJointIssuesUnchanged':deepcopy(doc['explicitJointIssues'])}
        for n,t in enumerate(rec['workedCases']):cases.append({'id':t.split(':',1)[0],'spellId':ident,'originalTextUnchanged':t,'source':info(p),'pointer':prior['recordPointer']+f'/workedCases/{n}'})
        for key in ['catalog','core']:ck('Underlying '+key+' '+ident,bind(R/card['source'][key+'Path'])['sha256']==card['source'][key+'Sha256'])
    inherited=[]
    for n in list(range(15))+[22,30,32,33,36,38,39,40,42,46,56,60,68,80,91,92]:
        e=reg['entries'][n];b=e['currentAuthoritativeSource'];a=bind(G/b['path']);ck('Exact accepted authority '+str(n),a['bytes']==b['bytes'] and a['sha256']==b['sha256']);inherited.append({'registryPointer':f'/entries/{n}','completeEntryUnchanged':deepcopy(e),'scopeLimit':'Exact accepted source only; no borrowed passenger, forced crossing, plane taxonomy or new custody exception.'})
    counterparts=[]
    for ident in ['dimensional-door','dimensional-anchor','arcane-portal','alignment-portal','faction-portal','elemental-displacement']:
        entry=next(e for e in index['entries'] if e['id']==ident);ck('Reviewed counterpart '+ident,entry['authoredStatus']=='reviewed-authored-operational-playtest');p=(ip.parent/entry['procedureFile']).resolve();doc=read(p);ptr=entry.get('wholeCardPointer',entry['procedurePointer']);counterparts.append({'spellId':ident,'source':bind(p),'pointer':ptr,'completeCurrentCard':deepcopy(at(doc,ptr)),'completeSharedRules':deepcopy(doc.get('sharedRules',{})),'indexEntry':deepcopy(entry)})
    palp=R/'data/public/class_playtests/paladin.json';pal=read(palp);blocks=[]
    for n in [41,43,130]:blocks.append({'source':info(palp),'pointer':f'/cards/{n}','completeCardUnchanged':deepcopy(pal['cards'][n])})
    ck('Three exact transport predicates',[b['completeCardUnchanged']['name'] for b in blocks]==['No Escape','Verdict Absolute','Reign of Ashes'])
    questions=[{'id':qid,'spellIds':ids,'exactSourceOrConflict':promise,'options':opts,'recommendationAndConsequences':rec,'decisionSelected':False} for qid,ids,promise,opts,rec in FORKS]
    findings=[
        {'id':'TR6-F01','classification':'HISTORICAL STATUS SUPERSEDED','finding':'Dimensional Door and Dimensional Anchor are accepted authored counterparts in AC4reviewed03; old shared text calling them unadopted is historical only. Universal Dimension Door remains distinct and pending.'},
        {'id':'TR6-F02','classification':'DISTINCT SOURCE CLASSIFICATION','finding':'Alignment Portal is planar/extradimensional nonteleport with sight-through and source-qualified forced traversal. Alignment Nexus Conjuration8 is both planar and teleport. Neither grants its classification to Mystic Gate, which earlier proposed same-plane opaque teleport crossings.'},
        {'id':'TR6-F03','classification':'EXACT WHOLE-BODY GEOMETRY','finding':'A centered unsqueezed Large10x10footprint has corner radius sqrt50>5 and does not lie inside a diameter10circle. A centered Medium5x5footprint has corner radius sqrt12.5<5. Original Circle scenarios did not give a body fixture; no original scenario is changed or claimed as a full geometry test.'},
        {'id':'TR6-F04','classification':'NEW CUSTODY CHOICE','finding':'TeleportObject loose worn gear/WIS differs from Shift no worn objects/CHA and InstantSummons no other current custodian. These are full deliberate proposed rules, not a generic teleport-custody inheritance.'},
        {'id':'TR6-F05','classification':'MISSING COMPLETE VEHICLE FIXTURE','finding':'Mystic Gate failed wagon scenario preserves the aperture-failure obligation. A successful vehicle transit still requires actual sourced coupled assembly, draft/driver/movement and full arrival geometry; no generic wagon profile is supplied here.'},
        {'id':'TR6-F06','classification':'CURRENT CLASS ENGINE','finding':'Historical Wizard baseline first-cast Dissonance text does not override the current prepared-first-distinct matrix. Circle30RP/30minutes is three base casts, excluding real study/acceptance/travel and any resource recovery needed by the actual selected caster.'},
        {'id':'TR6-F07','classification':'CREATURE-ORIGIN OBJECT BOUNDARY','finding':'True transformed creature-origin object retains actual identity/source targeting restrictions. It does not become an ordinary eligible item for TeleportObject/InstantSummons. Review current body-specific transport predicates for Shift rather than relying on obsolete shared creature-versus-object shorthand.'},
    ]
    ck('Six unique pending sources',len(records)==len(set(IDS))==6);ck('Twelve original cases',len(cases)==len({c['id'] for c in cases})==12);ck('Sixteen questions',len(questions)==16);ck('Catalog unchanged',index['authoredCounts']=={'reviewed':480,'pending':368})
    ck('Chest whole eligible mass',40+430==470<=500);ck('Chest whole excessive mass',40+430+40==510>500);ck('Circle three base casts',3*10==30);ck('Circle large square fails disk',5**2+5**2>5**2);ck('Circle medium square fits disk',2.5**2+2.5**2<5**2);ck('Recall600feet below mile',600<5280)
    root.mkdir();frozen=[]
    for b in sources.values():
        p=G/b['path'];ck('Source unchanged '+b['path'],info(p)==b);dst=root/'sources'/b['path'];dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(p.read_bytes());ck('Frozen byte equality '+b['path'],dst.read_bytes()==p.read_bytes());frozen.append({**b,'frozenCopy':dst.relative_to(G).as_posix()})
    result={'id':'TRANSPORT-6-CONFERENCE-01','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'PREAUTHORSHIP_CONFERENCE_PREPARED_UNSENT','developmentDirection':'video-game-only','records':records,'all12OriginalScenarios':cases,'completeOriginalSharedProposalsUnchanged':list(shared.values()),'sharedRouting':'Historical full shared proposals remain evidence. Each actual identity alone grants its passenger, custody, perception, range, support and activation scope. Current accepted source interfaces and class engine control inherited behavior; old unadopted labels and generic Wizard cadence are not live authority.','currentAcceptedInterfaceComparisons':inherited,'completeAcceptedCounterparts':counterparts,'completePaladinTransportPredicates':blocks,'semanticDelta':[{'spellId':r['spellId'],'riskTier':r['riskTier'],'fullEarlierNewChoices':r['completeOriginalRecordUnchanged']['newChoices'],'genuineQuestionIds':[q['id'] for q in questions if r['spellId'] in q['spellIds']]} for r in records],'questions':questions,'findings':findings,'riskCounts':{'B':1,'C':5},'currentVectors':[],'currentVectorScope':'Zero new complete current encounters. Twelve unchanged original scenarios remain requirements, with source-qualified actions, acquisition, legal endpoint geometry, bodies, custody and actual timing to be authored after actual decisions. Limited arithmetic/footprint preflight is not a full spell case or runtime test.','sourceBindings':list(sources.values()),'countsUnchanged':{'reviewed':480,'pending':368},'newRuleAdoptions':0,'runtimeTestsExecuted':0,'humanPlaytests':0,'cosmologyDecisions':0,'sourceInformationDeleted':0}
    out.write_bytes(encoded(result));check.write_bytes(encoded({'candidate':info(out),'checks':checks,'checkCount':len(checks),'sourceCount':len(sources),'fullProcedures':6,'originalCases':12,'newCurrentVectors':0,'questions':16,'failures':0,'validationScope':'Exact history/source/access/membership plus limited mass/time/footprint arithmetic; no final semantic acceptance or runtime.'}))
    (root/'MANIFEST.json').write_bytes(encoded({'candidate':info(out),'check':info(check),'files':list(sources.values()),'frozenSources':frozen,'sourceCount':len(sources),'newRuleAdoptions':0}))
    (root/'README.md').write_text('''# Transport6 preauthorship conference01

Read all six full earlier proposals, twelve unchanged original scenarios, complete current accepted counterparts and sixteen decision questions. Zero new current encounter vectors are submitted. The purpose is actual discussion of new local design before complete current cases and final exact acceptance.

Keep Universal Dimension Door separate from accepted Conjuration Dimensional Door. Preserve the actual500ft/100ft/60ft source fields and explicit new exceptions. Teleport Object, Dimensional Shift and Instant Summons intentionally have different custody/payload rules pending concurrence. Mystic Gate is proposed as a repeated same-plane opaque teleport doorway; Alignment Portal-specific planar nonteleport/forced-crossing/sight rules do not transfer. Circle is proposed as a paid ten-minute permanent site with local custodians, one studied accepted outbound link and a six-second origin cooldown, not a year ritual or new cosmology.

Exact current source bindings include Paladin transport blockers, accepted endpoint prevention and actual body/equipment/expedition rules. A10ft-diameter disk does not contain an unsqueezed Large10x10footprint. Successful vehicle transport still needs an actual sourced full vehicle/draft/capacity fixture. Circle30minutes/30RP counts three casts only, not study/travel/acceptance or character affordability. No generic prepared Wizard Dissonance example supersedes the current class engine.

Return downloadable complete per-spell and per-question dispositions and source-linked full proposed replacements where needed, retaining every old text and scenario obligation. No adoption, runtime/human/balance/cosmology/75-domain/whole-game/release approval;480reviewed/368pending unchanged.
''',encoding='utf8',newline='\n')
    with zipfile.ZipFile(archive,'x',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for n in ['README.md','MANIFEST.json']:z.write(root/n,n)
        z.write(out,'CANDIDATE.json');z.write(check,'PREFLIGHT.json')
        for b in frozen:z.write(G/b['frozenCopy'],'sources/'+b['path'])
    with zipfile.ZipFile(archive) as z:
        assert z.testzip() is None and z.read('CANDIDATE.json')==out.read_bytes()
        for b in frozen:assert z.read('sources/'+b['path'])==(G/b['frozenCopy']).read_bytes()
    b=info(archive);req.write_text(f'Please conduct Transport6 preauthorship conference using {archive.name} ({b["bytes"]} bytes; SHA256 {b["sha256"]}). Read all6 full original procedures,12 unchanged scenarios,16questions and full current accepted sources. Zero new current encounter vectors are submitted. Resolve Universal Dimension Door distinction, actual object/creature custody and atomic swap, local repeated Mystic Gate, one-shot Instant Summons and permanent Teleportation Circle configuration/activation. Preserve source-specific transport classification and actual Paladin blockers without inferring cosmology. A10ftdisk is not a10x10square; actual vehicle/swap reference geometry and class casting chronology remain required before full current cases. Return downloadable complete per-spell/per-question dispositions and full exact source-linked proposed replacements.480/368 unchanged; no adoption/runtime/human/balance/cosmology/domain closure.\n',encoding='utf8',newline='\n')
    prep.write_bytes(encoded({'archive':b,'candidate':info(out),'manifest':info(root/'MANIFEST.json'),'check':info(check),'request':info(req),'sourceCount':len(sources),'allArchiveSourcesVerified':True,'status':'Prepared UNSENT; actual GPT conference is separately tracked.','newRuleAdoptions':0}));print(json.dumps({'archive':b,'candidate':info(out),'preparation':info(prep),'sources':len(sources),'checks':len(checks),'originalCases':12,'questions':16}))

if __name__=='__main__':main()
